/* Public entry and explicitly labelled demo navigation. Not an authorization layer. */
(function () {
  let stage='welcome',course='primary',system='fr',audience='parent',billingPeriod='monthly';
  let recoveryToken=null,recoveryReady=false;
  const t=(fr,en)=>tr(fr,en);
  const root=document.getElementById('entry-root');
  data.children=data.children.map(normalizeChild);
  const family=()=>data.children.map((c,i)=>({c,i})).filter(({c})=>!c.professional);
  const spaces=()=>Array.isArray(data.entrySpaces)?data.entrySpaces:[];
  const spaceName=s=>({parent:t('Parent','Parent'),teacher:t('Enseignant','Teacher'),tutor:t('Accompagnateur','Learning coach'),student:t('Élève','Student')}[s.audience])+' · '+t(s.course==='college'?'Secondaire':'Primaire',s.course==='college'?'Secondary':'Primary')+' · '+(s.system==='en'?'English':'Français');
  function enterSpace(s){audience=s.audience;course=s.course;system=s.system;go(audience==='teacher'?'teacher':'family');}
  function rememberSpace(){if(!cloud)return;const list=spaces();if(!list.some(s=>s.audience===audience&&s.course===course&&s.system===system)){data.entrySpaces=[...list,{audience,course,system}];save();}}
  function spacesView(){return '<section class="entry-panel"><h1>'+t('Mes espaces','My spaces')+'</h1><p>'+t('Seuls les espaces que vous avez ajoutés apparaissent ici. Le premier s’ouvre à votre connexion.','Only spaces you have added appear here. The first opens when you sign in.')+'</p>'+spaces().map((s,i)=>'<section class="card"><h2>'+esc(spaceName(s))+'</h2>'+(i===0?'<p>'+t('Espace principal','Main space')+'</p>':'')+'<button data-saved-space="'+i+'">'+t('Ouvrir','Open')+'</button> '+(i?'<button class="secondary" data-main-space="'+i+'">'+t('Choisir comme espace principal','Make main space')+'</button>':'')+'</section>').join('')+'<button class="secondary" data-entry-go="worlds">'+t('Ajouter un autre espace','Add another space')+'</button><p>'+t('Ajouter un espace ne donne aucun accès aux dossiers d’autres personnes. Le partage nécessite une invitation.','Adding a space does not grant access to other people’s records. Sharing requires an invitation.')+'</p></section>';}
  const logo=()=>'<a href="#" class="entry-brand" data-entry-go="welcome">Klas <span>237</span><i aria-hidden="true"></i></a>';
  const demoNote=()=>cloud?'<p class="entry-note">'+t('Espace privé : vérifiez le statut de sauvegarde après vos saisies. Pour échanger avec une personne invitée, ouvrez les Cahiers partagés.','Private workspace: check the save status after making changes. Open Shared notebooks to exchange with invited members.')+'</p>':'<p class="entry-note">'+t('Démonstration : profils fictifs, sans compte créé. Les saisies disparaissent au rechargement.','Demo: fictional profiles, no account created. Entries disappear on reload.')+'</p>';
  function go(next){if(cloud&&next==='roles'&&spaces().length&&stage!=='worlds'&&stage!=='roles')next='spaces';if(stage==='reset-password'&&next!=='reset-password'){recoveryToken=null;recoveryReady=false;}stage=next;paint();const h=root.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'auto'});}
  function header(){return '<header class="entry-header">'+logo()+'<label>'+t('Langue','Language')+'<select id="entry-language"><option value="fr" '+(uiLanguage==='fr'?'selected':'')+'>Français</option><option value="en" '+(uiLanguage==='en'?'selected':'')+'>English</option></select></label>'+(stage==='pricing'?'':'<button class="entry-header-offers" data-entry-go="pricing">'+t('Les offres','Plans')+'</button>')+(stage==='welcome'?'<button class="secondary" data-entry-go="login">'+t('Se connecter','Sign in')+'</button>':'<button class="secondary" data-entry-go="welcome">'+t('Accueil','Home')+'</button>')+'</header>';}
  function accountInfo(){
    if(stage==='signup')return '<section class="entry-narrow entry-signup"><p class="entry-kicker">'+t('UN ESPACE À VOUS','YOUR OWN SPACE')+'</p><h1>'+t('Créer mon compte','Create my account')+'</h1><p>'+t('Un accès pilote gratuit de 14 jours, activé après confirmation de votre e-mail. À votre première connexion, choisissez le primaire ou le secondaire, puis votre espace parent, enseignant ou accompagnateur.','A free 14-day pilot, activated when you confirm your email. On first sign-in, choose primary or secondary, then your parent, teacher or learning coach space.')+'</p>'+(configured()?'<form id="entry-signup-form"><label for="entry-signup-email">'+t('Adresse e-mail','Email address')+'</label><input id="entry-signup-email" type="email" autocomplete="email" required><label for="entry-signup-password">'+t('Mot de passe (8 caractères minimum)','Password (at least 8 characters)')+'</label><input id="entry-signup-password" type="password" autocomplete="new-password" minlength="8" required><label for="entry-signup-confirm">'+t('Confirmer le mot de passe','Confirm password')+'</label><input id="entry-signup-confirm" type="password" autocomplete="new-password" minlength="8" required><label class="legal-accept"><input id="entry-terms" type="checkbox" required><span>'+t('Je suis majeur et j’accepte les <a href="legal.html#conditions" target="_blank" rel="noopener">conditions d’utilisation</a>. J’ai lu la <a href="legal.html#confidentialite" target="_blank" rel="noopener">politique de confidentialité</a>. Les profils mineurs sont accompagnés par un adulte responsable.','I am an adult and accept the <a href="legal.html#conditions" target="_blank" rel="noopener">terms of use</a>. I have read the <a href="legal.html#confidentialite" target="_blank" rel="noopener">privacy notice</a> (French). Minors use profiles with a responsible adult.')+'</span></label><button class="entry-submit" type="submit">'+t('Créer mon compte','Create my account')+'</button><p id="entry-signup-status" role="status" aria-live="polite"></p></form>':'<p class="entry-note">'+t('La création de compte est momentanément indisponible.','Account creation is temporarily unavailable.')+'</p>')+'<button class="entry-link" data-entry-go="login">'+t('J’ai déjà un compte','I already have an account')+'</button></section>';
    if(stage==='recovery')return '<section class="entry-narrow"><p class="entry-kicker">'+t('RETOUR À VOTRE ESPACE','BACK TO YOUR SPACE')+'</p><h1>'+t('Retrouver mon accès','Recover my access')+'</h1><p>'+t('Saisissez l’adresse e-mail de votre compte Klas 237. Si elle est enregistrée, vous recevrez un lien pour choisir un nouveau mot de passe.','Enter your Klas 237 account email. If it is registered, you will receive a link to choose a new password.')+'</p><form id="entry-recovery-form"><label for="entry-recovery-email">'+t('Adresse e-mail','Email address')+'</label><input id="entry-recovery-email" type="email" autocomplete="email" required><button class="entry-submit" type="submit">'+t('Recevoir le lien','Send recovery link')+'</button><p id="entry-recovery-status" role="status" aria-live="polite"></p></form><button class="entry-link" data-entry-go="login">'+t('Retour à la connexion','Back to sign in')+'</button></section>';
    if(stage==='reset-password')return '<section class="entry-narrow"><p class="entry-kicker">'+t('VOTRE COMPTE','YOUR ACCOUNT')+'</p><h1>'+t('Choisir un nouveau mot de passe','Choose a new password')+'</h1><p>'+t('Le lien reçu par e-mail ouvre cette page.','Your email link opens this page.')+'</p><form id="entry-reset-form"><label for="entry-new-password">'+t('Nouveau mot de passe (8 caractères minimum)','New password (at least 8 characters)')+'</label><input id="entry-new-password" type="password" autocomplete="new-password" minlength="8" required><label for="entry-confirm-password">'+t('Confirmer le mot de passe','Confirm password')+'</label><input id="entry-confirm-password" type="password" autocomplete="new-password" minlength="8" required><button class="entry-submit" type="submit" '+(!recoveryReady?'disabled':'')+'>'+t('Enregistrer le nouveau mot de passe','Save new password')+'</button><p id="entry-reset-status" role="status" aria-live="polite">'+(recoveryReady?'':t('Vérification du lien…','Checking your link…'))+'</p></form><button class="entry-link" data-entry-go="recovery">'+t('Demander un autre lien','Request another link')+'</button></section>';
    if(stage==='recovery-invalid')return '<section class="entry-narrow"><h1>'+t('Ce lien ne peut plus être utilisé','This link can no longer be used')+'</h1><p>'+t('Il a peut-être expiré ou déjà été utilisé. Demandez un nouveau lien de réinitialisation.','It may have expired or already been used. Request a new reset link.')+'</p><button data-entry-go="recovery">'+t('Demander un nouveau lien','Request a new link')+'</button></section>';
    return '<section class="entry-narrow"><h1>'+t('Rejoindre un accompagnement','Join a learning group')+'</h1><p>'+t('Connectez-vous avec votre compte pilote, puis ouvrez Cahiers partagés et collez le code reçu. Votre adresse e-mail doit être celle indiquée par le parent.','Sign in with your pilot account, then open Shared notebooks and paste the code you received. Your email must match the address specified by the parent.')+'</p><button data-entry-go="roles">'+t('Voir comment cela fonctionne','Explore how it works')+'</button><button class="entry-link" data-entry-go="login">'+t('Retour à la connexion','Back to sign in')+'</button></section>';
  }
  function openChild(index){selected=index;role=audience==='student'?'parent':audience;collegeAudience=audience==='student'?'student':'parent';course=data.children[index].track;stage='workspace';page=audienceStart(role==='parent'?collegeAudience:role,course);render();paint();window.scrollTo({top:0,behavior:'auto'});const h=document.querySelector('#screen h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
  function bind(){if(cloud){const h=root.querySelector('.entry-header');if(h){const b=document.createElement('button');b.className='secondary';b.textContent=t('Cahiers partagés','Shared notebooks');b.onclick=()=>window.openSharedNotebooks();h.append(b);}}root.querySelectorAll('[data-entry-go]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.entryGo);});root.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{course=b.dataset.world;system='fr';go('roles');});
    if(stage==='teacher'){
      const list=document.createElement('div');list.className='entry-role-list';
      data.children.forEach((c,i)=>{if(!c.professional||c.track!==course||c.subsystem!==system)return;const b=document.createElement('button');b.className='secondary';b.textContent=c.name+' · '+c.level+(c.subjects?' · '+c.subjects:'');b.onclick=()=>openChild(i);list.append(b);});
      if(list.children.length){const h=document.createElement('h2');h.textContent=t('Retrouver une classe','Reopen a class');list.prepend(h);const heading=root.querySelector('.entry-narrow h1, .entry-panel h1');if(heading)heading.after(list);}
    }
    root.querySelectorAll('[data-billing-period]').forEach(b=>b.onclick=()=>{billingPeriod=b.dataset.billingPeriod;paint();root.querySelector('[data-billing-period="'+billingPeriod+'"]').focus();});
    document.getElementById('entry-language').onchange=e=>{uiLanguage=e.target.value;try{localStorage.setItem('klas-ui-language',uiLanguage);}catch{}paint();};
    root.querySelectorAll('[data-entry-role]').forEach(b=>b.onclick=()=>{audience=b.dataset.entryRole;rememberSpace();go(audience==='teacher'?'teacher':'family');});
    root.querySelectorAll('[data-saved-space]').forEach(b=>b.onclick=()=>enterSpace(spaces()[Number(b.dataset.savedSpace)]));
    root.querySelectorAll('[data-main-space]').forEach(b=>b.onclick=()=>{const list=[...spaces()], chosen=list.splice(Number(b.dataset.mainSpace),1)[0];data.entrySpaces=[chosen,...list];save();paint();});
    root.querySelectorAll('[data-open-child]').forEach(b=>b.onclick=()=>openChild(Number(b.dataset.openChild)));
    if(stage==='roles'){const systemSelect=document.getElementById('entry-system');if(course==='college'){system='fr';systemSelect.value='fr';const upcoming=systemSelect.querySelector('option[value="en"]');if(upcoming){upcoming.disabled=true;upcoming.textContent=t('Anglophone · à venir','English-language · coming later');}}document.getElementById('entry-course').onchange=e=>{course=e.target.value;paint();};document.getElementById('entry-system').onchange=e=>{system=e.target.value;paint();};}
    const form=document.getElementById('entry-profile');if(form){const updateSubjects=()=>{if(stage!=='teacher')return;const level=form.elements.level.value,track=form.elements.track.value,sys=form.elements.subsystem.value;const list=track==='college'?collegeSubjects(level):primarySubjects({track:'primary',subsystem:sys,level});form.querySelector('#entry-subject-options').innerHTML=list.map(s=>'<option value="'+esc(s)+'"></option>').join('');form.elements.subjects.placeholder=track==='primary'?t('Ex. '+list.slice(0,2).join(', '),'e.g. '+list.slice(0,2).join(', ')):t('Ex. '+list.slice(0,2).join(', '),'e.g. '+list.slice(0,2).join(', '));};const update=()=>{const track=form.elements.track.value,sys=form.elements.subsystem.value,blocked=track==='college'&&sys==='en';if(stage==='teacher')form.elements.name.placeholder=track==='primary'?(sys==='en'?'Class 3 A':'CE2 A'):'4e B';form.elements.level.innerHTML=blocked?'':classEntries(track,sys).map(v=>'<option>'+esc(v)+'</option>').join('');form.querySelector('button').disabled=blocked;document.getElementById('profile-note').textContent=blocked?t('Ce cursus sera disponible dans une prochaine étape.','This curriculum will be available in a later stage.'):'';updateSubjects();};form.elements.track.onchange=update;form.elements.subsystem.onchange=update;form.elements.level.onchange=updateSubjects;update();form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(!values.name.trim())return;const c=normalizeChild(values);if(stage==='teacher'){c.professional=true;c.professionalRole='teacher';c.subjects=values.subjects;}data.children.push(c);save();if(stage==='teacher')openChild(data.children.length-1);else{course=c.track;system=c.subsystem;go('family');}};}
    const show=document.getElementById('entry-show-password');if(show)show.onclick=()=>{const p=document.getElementById('entry-password');p.type=p.type==='password'?'text':'password';show.textContent=p.type==='password'?t('Afficher','Show'):t('Masquer','Hide');};
    const signupForm=document.getElementById('entry-signup-form');if(signupForm)signupForm.onsubmit=async e=>{e.preventDefault();const button=signupForm.querySelector('button[type="submit"]'),status=document.getElementById('entry-signup-status'),password=document.getElementById('entry-signup-password').value,confirmation=document.getElementById('entry-signup-confirm').value;if(signupForm&&!signupForm.checkValidity()){signupForm.reportValidity();return;}if(password!==confirmation){status.textContent=t('Les mots de passe ne correspondent pas.','Passwords do not match.');return;}button.disabled=true;status.textContent=t('Création du compte…','Creating your account…');try{await signUp(document.getElementById('entry-signup-email').value,password);signupForm.reset();signupForm.querySelectorAll('input,label,button').forEach(el=>el.hidden=true);status.textContent=t('Demande d’inscription prise en compte. Consultez votre boîte e-mail et vos spams pour confirmer votre adresse, puis utilisez « J’ai déjà un compte » ci-dessous. Si aucun message n’arrive, utilisez « Besoin d’aide ? ».','Sign-up request received. Check your inbox and spam folder to confirm your email, then use “I already have an account” below. If no email arrives, use the help button.');status.scrollIntoView({block:'center',behavior:'smooth'});}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
    const recoveryForm=document.getElementById('entry-recovery-form');if(recoveryForm)recoveryForm.onsubmit=async e=>{e.preventDefault();if(!configured())return;const button=recoveryForm.querySelector('button[type="submit"]'),status=document.getElementById('entry-recovery-status');button.disabled=true;status.textContent=t('Demande en cours…','Requesting a link…');try{await api('/auth/v1/recover?redirect_to='+encodeURIComponent('https://klas237.netlify.app/'),{method:'POST',body:JSON.stringify({email:recoveryForm.elements['entry-recovery-email'].value.trim()})});recoveryForm.reset();status.textContent=t('Si cette adresse possède un compte, un lien vient d’être envoyé. Consultez aussi les courriers indésirables.','If this address has an account, a link has been sent. Check your spam folder too.');}catch(error){status.textContent=error.status===429?t('Trop de demandes. Réessayez un peu plus tard.','Too many requests. Try again later.'):t('Envoi impossible pour le moment. Réessayez plus tard.','Unable to send a link right now. Try again later.');}finally{button.disabled=false;}};
    const resetForm=document.getElementById('entry-reset-form');if(resetForm)resetForm.onsubmit=async e=>{e.preventDefault();const status=document.getElementById('entry-reset-status'),button=resetForm.querySelector('button[type="submit"]'),password=resetForm.elements['entry-new-password'].value,confirmation=resetForm.elements['entry-confirm-password'].value;if(password!==confirmation){status.textContent=t('Les mots de passe ne correspondent pas.','Passwords do not match.');return;}if(!recoveryReady||!recoveryToken){go('recovery-invalid');return;}button.disabled=true;status.textContent=t('Enregistrement…','Saving…');try{await api('/auth/v1/user',{method:'PUT',headers:{Authorization:'Bearer '+recoveryToken},body:JSON.stringify({password})});const token=recoveryToken;recoveryToken=null;recoveryReady=false;try{await api('/auth/v1/logout',{method:'POST',headers:{Authorization:'Bearer '+token}});}catch{}go('login');document.getElementById('entry-login-status').textContent=t('Mot de passe modifié. Connectez-vous avec le nouveau mot de passe.','Password changed. Sign in with your new password.');}catch(error){status.textContent=error.status===401? t('Ce lien a expiré. Demandez-en un autre.','This link has expired. Request another one.'):t('Modification impossible. Essayez un autre mot de passe ou demandez un nouveau lien.','Unable to update. Try another password or request a new link.');button.disabled=false;}};
    const loginForm=document.getElementById('entry-login-form');if(loginForm)loginForm.onsubmit=async e=>{e.preventDefault();if(!configured())return;const button=loginForm.querySelector('.entry-submit'),status=document.getElementById('entry-login-status');button.disabled=true;status.textContent=t('Connexion…','Signing in…');try{await signIn(document.getElementById('entry-email').value,document.getElementById('entry-password').value);render();toast(t('Bienvenue dans votre espace personnel.','Welcome to your private workspace.'));}catch(error){if(error.code==='ACCESS_EXPIRED'){go('billing');}else{status.textContent=error.message;}}finally{button.disabled=false;}};
    const pay=document.getElementById('entry-start-payment');if(pay)pay.onclick=async()=>{pay.disabled=true;const status=document.getElementById('entry-billing-status');status.textContent=t('Préparation de la page de paiement…','Preparing the checkout…');try{const result=await api('/functions/v1/klas-fapshi',{method:'POST',body:JSON.stringify({action:'start'})});if(result.mode!=='live')throw Error(t('Les paiements réels ne sont pas encore ouverts.','Real payments are not open yet.'));sessionStorage.setItem('klas-payment-order',result.orderId);window.location.assign(result.link);}catch(error){status.textContent=error.message||t('Le paiement est momentanément indisponible.','Payment is currently unavailable.');pay.disabled=false;}};
    const check=document.getElementById('entry-check-payment');if(check)check.onclick=async()=>{const id=sessionStorage.getItem('klas-payment-order');const status=document.getElementById('entry-billing-status');if(!id){status.textContent=t('Aucun paiement à vérifier sur cet appareil.','No payment to check on this device.');return;}check.disabled=true;try{const result=await api('/functions/v1/klas-fapshi',{method:'POST',body:JSON.stringify({action:'status',orderId:id})});if(result.status==='SUCCESSFUL'&&result.accessUpdated){sessionStorage.removeItem('klas-payment-order');status.textContent=t('Paiement confirmé. Reconnectez-vous pour ouvrir votre espace.','Payment confirmed. Sign in again to open your space.');}else status.textContent=t('Statut du paiement : ','Payment status: ')+result.status;}catch{status.textContent=t('Vérification momentanément indisponible. Réessayez plus tard.','Status check is currently unavailable. Try again later.');}finally{check.disabled=false;}};
    const billingLogout=document.getElementById('entry-billing-logout');if(billingLogout)billingLogout.onclick=async()=>{try{await api('/auth/v1/logout',{method:'POST'});}catch{}session=null;go('login');};
  }
  /* Maquette fidèle : un panneau éditorial, des visuels par univers et une
     entrée qui raconte le rôle avant de montrer les outils. */
  function entryPattern(){return '<div class="entry-pattern" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div>';}
  function entryPanelKicker(fr,en){root.dataset.entryReady=configured()?'ready':'demo';return '<p class="entry-kicker">'+t(fr,en)+'</p>';}
  function entryWorld(track){const primary=track==='primary';return '<article class="entry-world '+(primary?'primary-world':'secondary-world')+'"><div class="entry-world-visual"><img src="assets/entry-'+(primary?'primary':'secondary')+'.webp" alt="" width="960" height="540" loading="eager"></div><div class="entry-world-copy"><div class="entry-world-meta"><span>'+t(primary?'PRIMAIRE':'SECONDAIRE',primary?'PRIMARY':'SECONDARY')+'</span><small>'+t(primary?'SIL → CM2 · Class 1–6':'6e → 3e',primary?'SIL → CM2 · Class 1–6':'6e → 3e')+'</small></div><h2>'+t(primary?'Apprendre et grandir ensemble.':'Comprendre et gagner en autonomie.',primary?'Learn and grow together.':'Understand and grow independent.')+'</h2><div class="entry-world-badges"><b>'+t(primary?'Francophone':'Francophone',primary?'French-language':'French-language')+'</b>'+(primary?'<b>English</b>':'')+'<b>'+t(primary?'Suivi simple':'Suivi par matière',primary?'Simple check-in':'Subject tracking')+'</b></div><button data-world="'+(primary?'primary':'college')+'">'+t(primary?'Découvrir le primaire →':'Découvrir le secondaire →',primary?'Explore primary →':'Explore secondary →')+'</button></div></article>';}
  function welcome(){
    const ico={
      book:'<path d="M4 5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0-2 2V5Zm0 16a2 2 0 0 1 2-2h13"/><path d="M9 7h6M9 11h4"/>',
      knot:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
      hands:'<path d="M12 21s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.6-7 10-7 10Z"/>',
      class:'<path d="M4 4h16v11H4zM8 21h8M12 15v6"/><path d="M8 8h8M8 11h5"/>',
      target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
      wifi:'<path d="M5 12.5a10 10 0 0 1 14 0M8.5 16a5 5 0 0 1 7 0M2 9a15 15 0 0 1 20 0"/><circle cx="12" cy="19.5" r=".8"/><path d="m3 3 18 18"/>',
      lang:'<path d="M4 5h9M8.5 3v2M6 5c0 4 3 7 6 8M11 5c-1 4-4 7-7 8"/><path d="m13 21 4-9 4 9M14.5 18h5"/>',
      shield:'<path d="M12 3 4 7v6c0 4.4 3.4 7 8 8 4.6-1 8-3.6 8-8V7l-8-4Z"/><path d="m9 12 2 2 4-5"/>',
      map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Z"/><path d="M9 3v15M15 6v15"/>'
    };
    const icon=k=>'<span class="kx-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+ico[k]+'</svg></span>';
    const pain=(k,who,q,a)=>'<article class="kx-pain"><p class="kx-who">'+icon(k)+who+'</p><blockquote>« '+q+' »</blockquote><p class="kx-answer"><b>'+t('Avec Klas 237','With Klas 237')+'</b>'+a+'</p></article>';
    const step=(n,title,text)=>'<li><span class="kx-step-num" aria-hidden="true">'+n+'</span><h3>'+title+'</h3><p>'+text+'</p></li>';
    const fit=(k,title,text)=>'<li>'+icon(k)+'<div><h3>'+title+'</h3><p>'+text+'</p></div></li>';
    return '<section class="new-welcome kx-hero"><div class="welcome-copy"><p class="entry-kicker">'+t('CAMEROUN · PRIMAIRE &amp; SECONDAIRE · 2026—2027','CAMEROON · PRIMARY &amp; SECONDARY · 2026—2027')+'</p><h1>'+t('De petits pas.<br>De grandes<br><em>réussites.</em>','Small steps.<br>Big<br><em>achievements.</em>')+'</h1><p class="kx-lead">'+t('Le soir, devant le cahier, on ne sait pas toujours comment aider. Klas 237 vous donne <strong>la prochaine petite action</strong> : partir de ce qui a été vu en classe, repérer ce qui bloque, essayer ensemble. Dix minutes suffisent.','In the evening, in front of the exercise book, it is not always clear how to help. Klas 237 gives you <strong>the next small step</strong>: start from what was covered in class, spot what is blocking, try together. Ten minutes is enough.')+'</p><div class="kx-cta"><button data-entry-go="signup">'+t('Essayer gratuitement 14 jours','Try free for 14 days')+'</button><button class="secondary kx-demo" data-entry-go="worlds">'+t('Voir la démo, sans compte','See the demo, no account')+'</button></div><p class="trial-caption">'+t('Sans carte ni paiement. Un e-mail suffit pour créer votre compte.','No card, no payment. An email address is all you need.')+'</p><ul class="kx-trust" aria-label="'+t('En bref','At a glance')+'"><li>'+t('Parents','Parents')+'</li><li>'+t('Enseignants','Teachers')+'</li><li>'+t('Accompagnateurs','Learning coaches')+'</li><li>'+t('Français · English','Français · English')+'</li></ul></div><figure><img src="assets/entry-family.webp" alt="'+t('Une maman et sa fille travaillent ensemble à la maison.','A mother and daughter learning together at home.')+'" width="960" height="640"><figcaption>'+t('Petit à petit, la confiance grandit.','Step by step, confidence grows.')+'</figcaption></figure></section>'+
    '<section class="kx-section kx-pains" aria-labelledby="kx-pains-title"><p class="entry-kicker">'+t('LE PROBLÈME QUE NOUS RÉSOLVONS','THE PROBLEM WE SOLVE')+'</p><h2 id="kx-pains-title">'+t('Chacun veut aider l’enfant. Personne n’a le temps de tout refaire.','Everyone wants to help the child. Nobody has time to redo everything.')+'</h2><div class="kx-pain-grid">'+
      pain('hands',t('Parent','Parent'),t('Je ne connais pas la méthode de l’école et j’ai peur de l’embrouiller.','I don’t know the school’s method and I’m afraid of confusing them.'),t('On part de l’exemple du cahier, avec des mots simples et un essai à faire ensemble. Vous accompagnez, l’enfant répond.','You start from the exercise-book example, with simple words and one try together. You guide; the child answers.'))+
      pain('class',t('Enseignant','Teacher'),t('Ma classe est nombreuse : je ne vois pas à temps qui décroche, ni sur quoi.','My class is large: I can’t see in time who is falling behind, or on what.'),t('Les notions à reprendre et les bilans après évaluation sont rassemblés, pour ajuster la séance suivante.','Topics to revisit and post-assessment reviews are gathered, so you can adjust the next lesson.'))+
      pain('target',t('Accompagnateur','Learning coach'),t('Je ne sais pas ce qui a été vu en classe, alors je recommence tout.','I don’t know what was covered in class, so I start over.'),t('Vous partez du blocage précis noté par la famille, puis vous gardez l’essai, le résultat et la suite.','You start from the exact difficulty noted by the family, then record the attempt, result and next step.'))+
    '</div></section>'+
    '<section class="kx-section kx-method" aria-labelledby="kx-method-title"><div class="kx-method-head"><p class="entry-kicker">'+t('LA MÉTHODE KLAS 237','THE KLAS 237 METHOD')+'</p><h2 id="kx-method-title">'+t('Trois gestes, chaque soir.','Three moves, every evening.')+'</h2><p>'+t('Un appui, pas une réponse à copier. L’enfant réfléchit ; l’outil propose un indice ou un autre exemple ; l’adulte vérifie avec le cahier.','Support, not an answer to copy. The child thinks; the tool offers a hint or another example; the adult checks against the exercise book.')+'</p></div><ol class="kx-steps">'+
      step('1',t('Ce qu’il a vu','What was covered'),t('On ouvre le cahier du jour. Pas de nouveau cours.','Open today’s exercise book. No new lesson.'))+
      step('2',t('Où ça bloque','Where it’s stuck'),t('On nomme une seule difficulté, avec ses mots.','Name one difficulty, in their own words.'))+
      step('3',t('On essaie ensemble','We try together'),t('Un exemple simple, un essai, puis il refait seul.','One simple example, one try, then they do it alone.'))+
    '</ol><button class="secondary kx-demo" data-entry-go="worlds">'+t('Essayer la méthode dans la démo →','Try the method in the demo →')+'</button></section>'+
    '<section class="kx-section kx-fit" aria-labelledby="kx-fit-title"><p class="entry-kicker">'+t('PENSÉ POUR ICI','DESIGNED FOR HERE')+'</p><h2 id="kx-fit-title">'+t('Fait pour l’école camerounaise, pas adapté après coup.','Built for Cameroonian school, not adapted afterwards.')+'</h2><ul class="kx-fit-grid">'+
      fit('map',t('Du SIL au CM2, de la 6e à la 3e','From SIL to CM2, from 6e to 3e'),t('Les niveaux, matières et repères du programme, jusqu’au chemin vers le CEP.','Levels, subjects and curriculum milestones, up to the path to the CEP.'))+
      fit('lang',t('Francophone et anglophone','French- and English-language'),t('Primaire dans les deux sous-systèmes ; interface en français ou en anglais.','Primary in both subsystems; interface in French or English.'))+
      fit('wifi',t('Même sans connexion','Even offline'),t('Des fiches légères à télécharger avant de manquer de réseau.','Light activity cards to download before the network drops.'))+
      fit('shield',t('Des données prudentes','Careful with data'),t('Pas de photo ni de nom complet demandés. Les profils mineurs restent sous la responsabilité d’un adulte.','No photo or full name required. Minors’ profiles stay under an adult’s responsibility.'))+
    '</ul></section>'+
    '<section class="kx-section kx-final"><h2>'+t('Commencez ce soir, avec un seul devoir.','Start tonight, with one piece of homework.')+'</h2><p>'+t('14 jours offerts, puis à partir de 2 500 FCFA par mois pour une famille (tarifs proposés, paiement pas encore ouvert).','14 days free, then from 2,500 FCFA a month for a family (proposed prices; payment not open yet).')+'</p><div class="kx-cta"><button data-entry-go="signup">'+t('Créer mon compte gratuit','Create my free account')+'</button><button class="secondary" data-entry-go="pricing">'+t('Comparer les offres','Compare plans')+'</button></div></section>';}
  function worlds(){return '<section class="entry-panel"><p class="entry-kicker">'+t('ÉTAPE 1 · LE CURSUS','STEP 1 · THE PATHWAY')+'</p><h1>'+t('À chacun son univers.','A world for every learner.')+'</h1><p class="entry-lead">'+t('Choisissez le cursus de l’enfant ou de votre classe. Vous pourrez changer d’espace à tout moment.','Choose your child’s or class’s pathway. You can switch spaces at any time.')+'</p><div class="new-world-grid">'+entryWorld('primary')+entryWorld('college')+'</div>'+demoNote()+'</section>';}

  function login(){const ready=configured();return '<section class="entry-panel entry-panel-login">'+entryPanelKicker('VOTRE CARNET SCOLAIRE','YOUR SCHOOL RECORD')+'<h1>'+t('Heureux de vous retrouver.','Welcome back.')+'</h1><p class="entry-lead">'+t('La maison, l’école et l’accompagnement avancent dans le même sens.','Home, school and learning support move in the same direction.')+'</p><img class="entry-family-art" src="assets/entry-family.webp" alt="'+t('Une mère accompagne sa fille dans ses devoirs.','A mother helps her daughter with homework.')+'" width="960" height="540" fetchpriority="high"><section class="entry-form-block"><h2>'+t('Connectez-vous à votre espace.','Sign in to your space.')+'</h2>'+(ready?'<p class="entry-note">'+t('Votre espace personnel est sauvegardé. Sur un appareil partagé, déconnectez-vous après utilisation.','Your private space is saved. Sign out after using a shared device.')+'</p>':'')+(!ready?'<p class="entry-note">'+t('Les comptes personnels ne sont pas encore ouverts. Vous pouvez découvrir le parcours avec des profils fictifs.','Personal accounts are not open yet. Explore the journey with fictional profiles.')+'</p>':'')+'<form id="entry-login-form"><label for="entry-email">'+t('Adresse e-mail','Email address')+'</label><input id="entry-email" type="email" autocomplete="username" placeholder="'+t('Votre adresse e-mail','Your email address')+'" '+(!ready?'disabled':'required')+'><label for="entry-password">'+t('Mot de passe','Password')+'</label><div class="entry-password"><input id="entry-password" type="password" autocomplete="current-password" placeholder="'+t('Votre mot de passe','Your password')+'" '+(!ready?'disabled':'required')+'><button type="button" id="entry-show-password" class="entry-link">'+t('Afficher','Show')+'</button></div><button type="button" class="entry-link" data-entry-go="recovery">'+t('Mot de passe oublié ?','Forgot password?')+'</button><button class="entry-submit" '+(!ready?'disabled':'')+'>'+t('Me connecter','Sign in')+'</button><p id="entry-login-status" role="status"></p></form><div class="entry-account-links"><button class="entry-link" data-entry-go="signup">'+t('Créer un compte','Create an account')+'</button><button class="entry-link" data-entry-go="invite">'+t('J’ai une invitation','I have an invitation')+'</button></div>'+(!cloud?'<button class="secondary" data-entry-go="worlds">'+t('Explorer la démonstration','Explore the demo')+'</button>':'<button class="secondary" data-entry-go="family">'+t('Retrouver mes enfants','View my children')+'</button>')+'</section>'+entryPattern()+'</section>';}
  function periodPrice(base){
    const months=billingPeriod==='annual'?12:billingPeriod==='quarterly'?3:1;
    const total=billingPeriod==='annual'?base*10:billingPeriod==='quarterly'?base*2.7:base;
    const fmt=n=>new Intl.NumberFormat(uiLanguage==='en'?'en-GB':'fr-FR',{maximumFractionDigits:0}).format(n);
    const saving=base*months-total;
    return fmt(total)+' FCFA <small>'+t('pour ','for ')+months+' '+t(months===1?'mois':'mois','month'+(months===1?'':'s'))+' · '+t('à régler en une fois','paid in one payment')+'</small><small>'+(months>1?t('Soit environ ','About ')+fmt(total/months)+' FCFA / '+t('mois','month')+' · '+fmt(saving)+' FCFA '+t('économisés','saved'):t('Sans engagement · renouvelez quand vous le souhaitez.','No commitment · renew whenever you choose.'))+'</small>';
  }
  function periodSelector(){
    const options=[['monthly',t('Mensuel','Monthly'),t('Souplesse','Flexibility')],['quarterly',t('Trimestriel','Quarterly'),t('−10 %','−10%')],['annual',t('Annuel','Annual'),t('2 mois offerts','2 months included')]];
    const benefit=billingPeriod==='annual'?t('Douze mois de continuité, vacances comprises, au prix de dix mois. Pour installer des habitudes et retrouver son suivi toute l’année.','Twelve months of continuity, including holidays, for the price of ten. Build habits and keep your records throughout the year.'):billingPeriod==='quarterly'?t('Trois mois pour suivre une période de travail et faire le point régulièrement, avec 10 % d’économie. La période commence à l’activation, quelle que soit la date du trimestre scolaire.','Three months to follow a study period and review regularly, with 10% savings. The period starts at activation, independently of school-term dates.'):t('Un mois pour avancer à son rythme, avec un montant de départ plus accessible. Renouvelez seulement lorsque vous le souhaitez.','One month to work at your own pace, with a lower initial payment. Renew only when you choose.');
    return '<div class="entry-periods" role="group" aria-label="'+t('Durée de l’abonnement','Subscription duration')+'">'+options.map(([key,label,badge])=>'<button class="secondary" data-billing-period="'+key+'" aria-pressed="'+(billingPeriod===key)+'">'+label+'<small>'+badge+'</small></button>').join('')+'</div><p class="entry-period-benefit" role="status">'+benefit+'</p><p class="entry-period-note">'+t('Les mêmes outils pour chaque durée. Économies calculées par rapport au tarif mensuel. Tarifs proposés ; paiement pas encore ouvert.','The same tools for every duration. Savings compared with the monthly rate. Proposed prices; payments are not open yet.')+'</p>';
  }
  function offerCard(name,price,who,items,ai,art,featured){
    return '<article class="entry-offer-card'+(featured?' entry-offer-featured':'')+'"><img src="assets/'+art+'.webp" alt="" width="960" height="540" loading="lazy"><div class="entry-offer-body">'+(featured?'<span class="kx-badge">'+t('Le plus accessible','Most affordable')+'</span>':'')+'<p class="entry-offer-audience">'+who+'</p><h2>'+name+'</h2><p class="entry-offer-price">'+price+'</p><p class="entry-offer-label">'+t('Outils déjà disponibles','Tools available now')+'</p><ul>'+items.map(item=>'<li>'+item+'</li>').join('')+'</ul><div class="entry-offer-ai"><strong>'+t('Avec l’IA intégrée · prévue','With integrated AI · planned')+'</strong><p>'+ai+'</p></div></div></article>';
  }
  function pricing(){
    return '<section class="entry-panel entry-pricing"><p class="entry-kicker">'+t('DES OUTILS POUR CHAQUE QUOTIDIEN','A PLAN FOR EACH DAY')+'</p><h1>'+t('Choisissez ce qui vous aide à avancer.','Choose what helps you move forward.')+'</h1><p class="entry-lead">'+t('Commencez par 14 jours gratuits avec un compte sauvegardé. Ensuite, l’accès s’arrête jusqu’au renouvellement. Vos données restent conservées.','Start with 14 free days and a saved account. Access then pauses until renewal. Your data remain saved.')+'</p>'+periodSelector()+'<div class="entry-offer-grid">'+
      offerCard(t('Famille','Family'),periodPrice(2500),t('PARENT · ÉLÈVE','PARENT · STUDENT'),[
        t('Organiser devoirs et révisions, du primaire au secondaire disponible.','Organise homework and revision in the available primary and secondary paths.'),
        t('Noter un point difficile et la prochaine étape après un contrôle.','Record a difficulty and the next step after an assessment.'),
        t('Suivre plusieurs profils dans le même compte et retrouver ses saisies.','Follow several profiles in one account and find saved entries.')
      ],t('Pour le parent : reformuler une consigne du cahier et proposer un autre exemple. Pour l’élève : donner un indice après son essai, puis le laisser répondre.','For the parent: rephrase an exercise-book instruction and suggest another example. For the learner: offer a hint after an attempt, then let them answer.'),'entry-family',true)+
      offerCard(t('Enseignant','Teacher'),periodPrice(5000),t('CLASSE · MATIÈRES','CLASS · SUBJECTS'),[
        t('Préparer les cours, exemples et essais à faire en classe.','Plan lessons, examples and class practice.'),
        t('Suivre les notions à reprendre et les bilans après évaluation.','Track topics to revisit and reviews after assessment.'),
        t('Garder plusieurs préparations et observations dans son espace.','Keep lesson plans and observations in your space.')
      ],t('Suggérer une autre façon d’expliquer une notion ou un exercice de vérification ; l’enseignant choisit, corrige et adapte à sa classe.','Suggest another explanation or a check-for-understanding exercise; the teacher chooses, corrects and adapts it to the class.'),'entry-teacher',false)+
      offerCard(t('Accompagnateur','Learning coach'),periodPrice(5000),t('SUIVI INDIVIDUEL','INDIVIDUAL SUPPORT'),[
        t('Préparer une séance à partir du besoin précis de l’élève.','Plan a session around a learner’s specific need.'),
        t('Noter l’essai, le résultat observé et la prochaine action.','Record the attempt, observed result and next action.'),
        t('Retrouver ses séances et bilans dans son espace.','Find sessions and reviews in your space.')
      ],t('Aider à varier l’exemple et à préparer une reprise ciblée à partir d’un blocage décrit ; l’accompagnateur observe la réponse réelle et décide de la suite.','Help vary an example and plan focused practice from a described difficulty; the coach observes the actual answer and decides what comes next.'),'entry-coach',false)+'</div>'+
      '<section class="entry-ai-method"><p class="entry-kicker">'+t('NOTRE RÈGLE','OUR APPROACH')+'</p><h2>'+t('Un appui, pas une réponse à copier.','Support, not an answer to copy.')+'</h2><ol><li>'+t('L’élève montre ce qu’il a déjà essayé.','The learner shows what they tried.')+'</li><li>'+t('L’outil propose un indice, une explication ou un autre exemple.','The tool offers a hint, an explanation or another example.')+'</li><li>'+t('L’élève réessaie ; l’adulte vérifie avec le cahier et l’enseignant.','The learner tries again; the adult checks against the exercise book and the teacher’s method.')+'</li></ol><p>'+t('Cette méthode guide déjà les exercices et fiches disponibles. L’IA personnalisée intégrée est encore en préparation.','This method already guides the available exercises and cards. Integrated personalised AI is still in development.')+'</p></section>'+
      '<p class="entry-offer-notice">'+t('Ces tarifs décrivent les offres envisagées. Pour le moment, un même accès pilote donne les outils disponibles selon l’espace choisi ; les forfaits distincts, l’IA intégrée et les paiements ne sont pas encore activés. Aucun prélèvement automatique.','These are proposed plans. For now, one pilot access provides the available tools for the chosen space; separate plans, integrated AI and payments are not active yet. No automatic charge.')+'</p><div class="entry-offer-actions"><button data-entry-go="signup">'+t('Essayer gratuitement 14 jours','Try 14 days free')+'</button><button class="secondary" data-entry-go="login">'+t('J’ai déjà un compte','I already have an account')+'</button></div></section>';
  }
  function billing(){return '<section class="entry-narrow entry-billing"><p class="entry-kicker">'+t('MON ACCÈS','MY ACCESS')+'</p><h1>'+t('Votre essai est terminé.','Your trial has ended.')+'</h1><p>'+t('L’accès à votre espace est suspendu. Votre compte et vos données restent conservés. Consultez les offres envisagées pour la suite.','Access to your space is paused. Your account and data remain saved. Review the proposed plans for what comes next.')+'</p><button class="secondary" data-entry-go="pricing">'+t('Comparer les offres','Compare plans')+'</button>'+(window.NDAB_CONFIG?.paymentEnabled?'<p class="entry-note">'+t('Le renouvellement Famille est de 2 500 FCFA pour 30 jours, sans prélèvement automatique.','Family renewal is 2,500 FCFA for 30 days, without automatic charges.')+'</p><button id="entry-start-payment" class="entry-submit">'+t('Renouveler mon accès Famille','Renew Family access')+'</button>':'<p class="entry-note">'+t('Le paiement est en cours de mise en place. Aucun règlement n’est demandé pour le moment.','Payments are being set up. No payment is requested yet.')+'</p>')+'<button id="entry-check-payment" class="secondary">'+t('Vérifier un paiement','Check a payment')+'</button><p id="entry-billing-status" role="status" aria-live="polite"></p><button id="entry-billing-logout" class="entry-link">'+t('Se déconnecter','Sign out')+'</button></section>';}
  function roleCard(key,name,desc,asset){return '<button class="entry-role entry-role-card" data-entry-role="'+key+'"><span class="entry-role-art"><img src="assets/'+asset+'.webp" alt="" width="960" height="540" loading="lazy"></span><span class="entry-role-copy"><strong>'+name+'</strong><span>'+desc+'</span></span><span class="entry-role-arrow" aria-hidden="true">→</span></button>';}
  function roles(){const secondaryEnglish=course==='college'&&system==='en';return '<section class="entry-panel entry-panel-roles">'+entryPanelKicker('ÉTAPE 2 · CHOISIR SON ESPACE','STEP 2 · CHOOSE YOUR SPACE')+'<h1>'+(cloud?t(spaces().length?'Quel espace souhaitez-vous ajouter ?':'Quel est votre espace principal ?',spaces().length?'Which space would you like to add?':'What is your main space?'):t('Quel espace souhaitez-vous découvrir ?','Which space would you like to explore?'))+'</h1><p class="entry-lead">'+t('Le même compte, mais les bons outils pour votre quotidien.','One account, with the right tools for your day.')+'</p><fieldset class="entry-system"><legend>'+t('Votre parcours scolaire','Your school pathway')+'</legend><label>'+t('Cursus','Stage')+'<select id="entry-course"><option value="primary" '+(course==='primary'?'selected':'')+'>'+t('Primaire','Primary')+'</option><option value="college" '+(course==='college'?'selected':'')+'>'+t('Secondaire · 6e à 3e','Secondary · 6e to 3e')+'</option></select></label><label>'+t('Sous-système','Curriculum')+'<select id="entry-system"><option value="fr" '+(system==='fr'?'selected':'')+'>'+t('Francophone','French-language')+'</option><option value="en" '+(system==='en'?'selected':'')+'>'+t('Anglophone','English-language')+'</option></select></label></fieldset>'+(secondaryEnglish?'<p class="entry-note">'+t('Le secondaire anglophone est prévu, mais son contenu n’est pas encore ouvert.','English-language secondary is planned, but its curriculum is not open yet.')+'</p>':'<div class="entry-role-grid">'+roleCard('parent',t('Parent ou responsable','Parent or guardian'),t('Suivre sans transformer l’année en corvée.','Follow without turning the year into a chore.'),'entry-family')+roleCard('teacher',t('Enseignant','Teacher'),t('Préparer, observer et ajuster la classe.','Plan, observe and adjust the class.'),'entry-teacher')+roleCard('tutor',t('Accompagnateur pédagogique','Learning coach'),t('Renforcer un point précis, seul ou en petit groupe.','Strengthen one precise point, alone or in a small group.'),'entry-coach')+(course==='college'?roleCard('student',t('Élève','Student'),t('Organiser son travail et demander de l’aide.','Organise your work and ask for help.'),'entry-secondary'):'')+'</div>')+entryPattern()+'</section>';}
  function familyView(){const hero=audience==='tutor'?'entry-coach':audience==='student'?'entry-secondary':'entry-family';const titleText=audience==='tutor'?t('Mes accompagnements','My students'):audience==='student'?t('Mon profil élève','My student profile'):t('Mes enfants','My children');const empty=t('Aucun profil dans ce cursus pour le moment.','No profile in this pathway yet.');const groups=[course].filter(track=>audience!=='student'||track==='college').map(track=>{const entries=family().filter(({c})=>c.track===track&&c.subsystem===system);return '<section class="entry-child-group '+(track==='primary'?'primary-group':'secondary-group')+'"><div class="entry-group-heading"><div><p class="entry-kicker">'+t(track==='primary'?'UNIVERS 01':'UNIVERS 02',track==='primary'?'WORLD 01':'WORLD 02')+'</p><h2>'+t(track==='primary'?'Primaire':'Secondaire',track==='primary'?'Primary':'Secondary')+'</h2></div><span>'+t(track==='primary'?(system==='en'?'Class 1 → Class 6':'SIL → CM2'):'6e → 3e',track==='primary'?(system==='en'?'Class 1 → Class 6':'SIL → CM2'):'6e → 3e')+'</span></div>'+(entries.length?entries.map(({c,i})=>'<article class="entry-child"><span class="entry-avatar '+(track==='primary'?'entry-avatar-primary':'entry-avatar-secondary')+'" aria-hidden="true"><span>'+esc(c.name.slice(0,1))+'</span></span><div><h3>'+esc(c.name)+'</h3><p>'+esc(c.level)+' · '+t(c.subsystem==='en'?'Anglophone':'Francophone',c.subsystem==='en'?'English-language':'French-language')+'</p></div><button data-open-child="'+i+'">'+t('Ouvrir','Open')+' <span aria-hidden="true">→</span></button></article>').join(''):'<p class="entry-empty">'+empty+'</p>')+'</section>';}).join('');return '<section class="entry-panel entry-panel-family">'+entryPanelKicker(audience==='tutor'?'ACCOMPAGNEMENT CIBLÉ':audience==='student'?'MON TRAVAIL':'MA FAMILLE',audience==='tutor'?'TARGETED SUPPORT':audience==='student'?'MY WORK':'MY FAMILY')+'<div class="entry-family-heading"><div><h1>'+titleText+'</h1><p class="entry-lead">'+t('Chaque profil garde son propre parcours, sa classe et sa prochaine action.','Each profile keeps its own pathway, class and next action.')+'</p></div><img src="assets/'+hero+'.webp" alt="" width="960" height="540" loading="eager"></div>'+(!cloud?demoNote():'')+groups+(audience==='parent'?'<button class="entry-add-child" data-entry-go="add-child">＋ '+t('Ajouter un enfant','Add a child')+'</button>':'')+'<p><button class="entry-link" data-entry-go="roles">'+t('Changer d’espace','Switch space')+'</button></p>'+entryPattern()+'</section>';}
  function profileForm(professional){const art=professional?'entry-teacher':'entry-family';return '<section class="entry-panel entry-panel-form">'+entryPanelKicker(professional?'ESPACE ENSEIGNANT · NOUVELLE CLASSE':'ESPACE FAMILLE · NOUVEAU PROFIL',professional?'TEACHER SPACE · NEW CLASS':'FAMILY SPACE · NEW PROFILE')+'<div class="entry-form-heading"><div><h1>'+t(professional?'Ma classe, mes matières':'Ajouter un enfant',professional?'My class and subjects':'Add a child')+'</h1><p class="entry-lead">'+t(professional?'Un contexte clair pour préparer les bonnes séances.':'Un profil simple pour suivre le quotidien sans pression.',professional?'A clear context for planning the right lessons.':'A simple profile for following the day without pressure.')+'</p></div><img src="assets/'+art+'.webp" alt="" width="960" height="540" loading="lazy"></div>'+demoNote()+'<form id="entry-profile"><label>'+t(professional?'Nom de la classe ou du groupe':cloud?'Prénom ou surnom':'Prénom ou surnom fictif',professional?'Class or group name':cloud?'First name or nickname':'Fictional first name or nickname')+'<input name="name" required maxlength="60" placeholder="'+(professional?(course==='primary'?(system==='en'?'Class 3 A':'CE2 A'):'4e B'):t('Ex. Emma','e.g. Emma'))+'"></label><label>'+t('Cursus','Stage')+'<select name="track" id="profile-track"><option value="primary" '+(course==='primary'?'selected':'')+'>'+t('Primaire','Primary')+'</option><option value="college" '+(course==='college'?'selected':'')+'>'+t('Secondaire','Secondary')+'</option></select></label><label>'+t('Sous-système','Curriculum')+'<select name="subsystem" id="profile-system"><option value="fr" '+(system==='fr'?'selected':'')+'>'+t('Francophone','French-language')+'</option><option value="en" '+(system==='en'?'selected':'')+'>'+t('Anglophone','English-language')+'</option></select></label><label>'+t('Classe','Class')+'<select name="level" id="profile-level"></select></label>'+(professional?'<label>'+t('Matières enseignées','Subjects taught')+'<input name="subjects" list="entry-subject-options" maxlength="200" placeholder="'+t('Ex. Toutes les matières / Mathématiques, PCT','e.g. All subjects / Mathematics')+'"></label><datalist id="entry-subject-options"></datalist><p class="entry-form-help">'+t('Au primaire, préparez plusieurs matières pour la classe. Au secondaire, précisez vos matières.','In primary, plan several subjects for the class. In secondary, specify your subjects.')+'</p>':'')+'<p id="profile-note" role="status"></p><button>'+t(professional?'Ouvrir mon espace enseignant':'Ajouter ce profil',professional?'Open my teacher space':'Add this profile')+'</button></form><button class="entry-link" data-entry-go="'+(professional?'roles':'family')+'">'+t('Retour','Back')+'</button>'+entryPattern()+'</section>';}
  function paint(){document.body.dataset.entry=stage;root.hidden=stage==='workspace';if(stage==='workspace')return;document.documentElement.lang=uiLanguage;root.innerHTML=header()+'<div class="entry-content">'+(stage==='welcome'?welcome():stage==='login'?login():stage==='pricing'?pricing():stage==='billing'?billing():stage==='spaces'?spacesView():stage==='worlds'?worlds():stage==='roles'?roles():stage==='family'?familyView():['teacher','add-child'].includes(stage)?profileForm(stage==='teacher'):accountInfo())+'</div><footer class="entry-footer">Klas 237 · JenguAI<nav aria-label="Informations légales"><a href="legal.html#mentions">Mentions légales</a><a href="legal.html#conditions">Conditions d’utilisation</a><a href="legal.html#confidentialite">Confidentialité</a><a href="legal.html#cookies">Cookies et stockage</a><a href="legal.html#contact">Contact</a></nav></footer>';bind();}
  const oldRender=render;
  render=function(){
    oldRender();
    document.body.toggleAttribute('data-private-spaces',cloud);
    if(cloud&&stage==='login'){if(spaces().length)enterSpace(spaces()[0]);else{audience='parent';stage='worlds';paint();}}
    let back=document.getElementById('entry-back');
    if(!back){back=document.createElement('button');back.id='entry-back';back.className='secondary';document.querySelector('main > header').prepend(back);}
    back.textContent=t('Mes espaces','My spaces');
    back.onclick=()=>go(cloud&&spaces().length?'spaces':'worlds');
    document.querySelectorAll('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();go('welcome');});
    const c=data.children[selected];
    if(c?.professional&&role==='teacher'){const p=document.querySelector('#audience-context p');if(p)p.textContent=c.name+' · '+c.level+(c.subjects?' · '+c.subjects:'');}
    const picker=document.querySelector('.course-picker');if(picker)picker.hidden=true;
    const profile=document.querySelector('.profile-select');if(profile)profile.hidden=true;
    if(stage==='workspace'&&['home','staff','parent-summary','college'].includes(page)&&!document.querySelector('.entry-workspace-art')){
      const art=document.createElement('img');
      art.className='entry-workspace-art';
      const asset=role==='teacher'?'teacher':role==='tutor'?'coach':currentCourse()==='college'?'secondary':'primary';
      art.src='assets/entry-'+asset+'.webp';
      art.alt='';art.width=900;art.height=600;
      document.getElementById('screen').prepend(art);
    }
  };
  const callback=new URLSearchParams(window.location.hash.slice(1));
  if(callback.get('type')==='recovery'&&callback.get('access_token')){recoveryToken=callback.get('access_token');stage='reset-password';history.replaceState(null,'',window.location.pathname+window.location.search);}
  else if(callback.has('error')||callback.get('type')==='recovery'){stage='recovery-invalid';history.replaceState(null,'',window.location.pathname+window.location.search);}
  else if(callback.get('type')==='signup'){stage='login';history.replaceState(null,'',window.location.pathname+window.location.search);}
  render();paint();
  if(stage==='reset-password')api('/auth/v1/user',{headers:{Authorization:'Bearer '+recoveryToken}}).then(()=>{if(stage==='reset-password'){recoveryReady=true;paint();}}).catch(()=>{recoveryToken=null;recoveryReady=false;go('recovery-invalid');});
}());
